  var mount = document.querySelector("[data-logo-marquee]");
  if (!mount) return;
  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c];
    });
  }
  function list(hidden) {
    var html = logos.map(function (logo) {
      var alt = hidden ? "" : esc(logo.name);
      return '<li><img src="' + logo.src + '" alt="' + alt + '" height="40" /></li>';
    }).join("");
    return '<ul class="v33-logo-marquee__list"' + (hidden ? ' aria-hidden="true"' : "") + ">" + html + "</ul>";
  }
  mount.innerHTML = '<div class="v33-logo-marquee__track">' + list(false) + list(true) + "</div>";
